def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]

    last_op = op[-1]
    last_me = me[-1]

    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c

    opp_coop_rate = op_c / float(n)

    if n <= 3:
        return 'C'

    window = min(20, n)
    recent_op = op[-window:]
    recent_c = sum(1 for x in recent_op if x == 'C')
    recent_rate = recent_c / float(window)

    streak_d = 0
    for x in reversed(op):
        if x == 'D':
            streak_d += 1
        else:
            break

    streak_c = 0
    for x in reversed(op):
        if x == 'C':
            streak_c += 1
        else:
            break

    # Endgame exploitation against cooperative opponents
    if n >= 92:
        if opp_coop_rate >= 0.75:
            return 'D'
        if opp_coop_rate <= 0.3:
            return 'D'
        return last_op

    if n >= 85:
        if opp_coop_rate >= 0.85:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if opp_coop_rate <= 0.2:
            return 'D'
        return last_op

    # Very naive always-cooperator: exploit sparingly
    if n >= 15 and op_d == 0:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent almost always defects: defend, rare probe
    if n >= 8 and op_d >= n - 2:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Long recent cooperation: maintain, but occasionally probe
    if recent_rate >= 0.85:
        if rng.random() < 0.05 and n >= 12:
            return 'D'
        return 'C'

    # Recent mostly cooperation
    if recent_rate >= 0.65:
        if last_op == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'C'

    # Respond to immediate defection
    if last_op == 'D':
        if streak_d >= 3:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if last_me == 'D':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'D'

    # Last op cooperated
    if streak_c >= 3:
        if recent_rate >= 0.5:
            return 'C'

    # Mixed regime: tit-for-tat with occasional noise
    if recent_rate >= 0.4:
        if last_op == 'C':
            if rng.random() < 0.05 and op_d >= 2:
                return 'D'
            return 'C'
        return 'D'

    # Low cooperation: defect most, probe occasionally
    if rng.random() < 0.15:
        return 'C'
    return 'D'
